/**
* TextRank Web Worker 实现
* 在后台线程中处理文本分析，避免阻塞主线程
*/
async function handleKeywordAnalysis(config) {
	const analysisResult = await safeAsync(async () => {
		const startTime = performance.now();
		const tr4w = new TextRankKeyword();
		tr4w.analyze(config.text, config.config);
		const result = {};
		if (config.options?.keywords) result.keywords = tr4w.getKeywords(config.options.keywords.num, config.options.keywords.wordMinLen);
		if (config.options?.keyphrases) result.keyphrases = tr4w.getKeyphrases(config.options.keyphrases.keywordsNum, config.options.keyphrases.minOccurNum);
		result.segmentation = {
			sentences: tr4w.sentences,
			wordsNoFilter: tr4w.wordsNoFilter,
			wordsNoStopWords: tr4w.wordsNoStopWords,
			wordsAllFilters: tr4w.wordsAllFilters
		};
		const endTime = performance.now();
		return {
			...result,
			duration: endTime - startTime
		};
	}, ErrorType.COMPUTATION_ERROR, {
		taskType: "keyword-analysis",
		textLength: config.text?.length,
		hasKeywords: !!config.options?.keywords,
		hasKeyphrases: !!config.options?.keyphrases
	});
	if (!analysisResult.ok) throw new Error(`关键词分析失败: ${analysisResult.error?.message || "未知错误"}`);
	return analysisResult.value;
}
async function handleSentenceAnalysis(config) {
	const analysisResult = await safeAsync(async () => {
		const startTime = performance.now();
		const tr4s = new TextRankSentence();
		tr4s.analyze(config.text, config.config);
		const result = {};
		if (config.options?.sentences) result.sentences = tr4s.getKeySentences(config.options.sentences.num, config.options.sentences.sentenceMinLen);
		if (config.options?.summary) result.summary = tr4s.getSummary(config.options.summary.num, config.options.summary.sentenceMinLen, config.options.summary.sortByIndex);
		result.segmentation = {
			sentences: tr4s.sentences,
			wordsNoFilter: tr4s.wordsNoFilter,
			wordsNoStopWords: tr4s.wordsNoStopWords,
			wordsAllFilters: tr4s.wordsAllFilters
		};
		const endTime = performance.now();
		return {
			...result,
			duration: endTime - startTime
		};
	}, ErrorType.COMPUTATION_ERROR, {
		taskType: "sentence-analysis",
		textLength: config.text?.length,
		hasSentences: !!config.options?.sentences,
		hasSummary: !!config.options?.summary
	});
	if (!analysisResult.ok) throw new Error(`句子分析失败: ${analysisResult.error?.message || "未知错误"}`);
	return analysisResult.value;
}
self.onmessage = async (event) => {
	const message = event.data;
	const messageResult = await safeAsync(async () => {
		const payload = dataTransfer.processReceivedData(message.payload);
		let data;
		switch (message.type) {
			case "analyze_keywords":
				data = await handleKeywordAnalysis(payload);
				break;
			case "analyze_sentences":
				data = await handleSentenceAnalysis(payload);
				break;
			default: throw new Error(`Unknown message type: ${message.type}`);
		}
		const result = {
			id: message.id,
			success: true,
			data,
			duration: data.duration
		};
		const { transferData, transferables, useTransferable } = dataTransfer.prepareDataForTransfer(result);
		const responseMessage = {
			id: message.id,
			type: "result",
			payload: transferData
		};
		if (useTransferable && transferables) {
			responseMessage.transferable = transferables;
			self.postMessage(responseMessage, transferables);
		} else self.postMessage(responseMessage);
		return result;
	}, ErrorType.WORKER_ERROR, {
		messageId: message.id,
		messageType: message.type
	});
	if (!messageResult.ok) {
		const result = {
			id: message.id,
			success: false,
			error: messageResult.error?.message || "未知错误"
		};
		self.postMessage({
			id: message.id,
			type: "error",
			payload: result
		});
	}
};
self.postMessage({
	id: "worker-ready",
	type: "result",
	payload: { message: "TextRank Worker is ready" }
});
//#endregion
